window.pofepaReady = (async () => {
  'use strict';
  const payload=JSON.parse(document.getElementById('site-data').textContent);
  const downloads=new Map();
  async function unpack(bytes){return JSON.parse(await new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))).text());}
  function fetchData(path){if(!downloads.has(path))downloads.set(path,(async()=>{const requestPath=payload.revision?path+(path.includes('?')?'&':'?')+'data='+payload.revision:path;const response=await fetch(requestPath,{cache:'no-cache'});if(!response.ok)throw new Error('Data download failed: '+response.status);return unpack(await response.arrayBuffer());})().catch(error=>{downloads.delete(path);throw error;}));return downloads.get(path);}
  const db=payload.bootstrap?await fetchData(payload.bootstrap):payload.compressed?await unpack(Uint8Array.from(atob(payload.compressed),c=>c.charCodeAt(0))):payload;
  const playerHistories=new Map();

  const {escape:E,search,stats,h2h}=Pofepa;
  const Evidence=PofepaEvidence;
  const app=document.getElementById('app');
  const map=rows=>new Map(rows.map(r=>[r.id,r]));
  const players=map(db.players), clubs=map(db.clubs), events=map(db.events), sources=map(db.sources);
  const statsByPlayer=new Map(db.players.map(p=>[p.id,p.stats||stats([],p.id)]));
  const matchesByPlayer=new Map();
  for(const m of db.matches) for(const id of [m.p1,m.p2]) { if(!matchesByPlayer.has(id))matchesByPlayer.set(id,[]); matchesByPlayer.get(id).push(m); }
  if(!db.lazy)for(const [id,rows] of matchesByPlayer)statsByPlayer.set(id,stats(rows,id));
  const latestPeriod=db.coverage.ranking_periods.at(-1);
  const latestGeneral=db.snapshots.find(s=>s.region==='national'&&s.period===latestPeriod&&s.list==='ΓΕΝΙΚΟΣ');
  const latestRows=new Map((latestGeneral?.rows||[]).map(r=>[r[0],r]));
  let lang='el';try{lang=localStorage.getItem('pofepa-lang')==='en'?'en':'el';}catch{}
  const L=(el,en)=>lang==='el'?el:en;
  const num=(v,digits=0)=>v==null?'—':new Intl.NumberFormat(lang==='el'?'el-GR':'en-GB',{maximumFractionDigits:digits}).format(v);
  const percent=v=>v==null?'—':num(v*100,1)+'%';
  const datefmt=value=>value?new Intl.DateTimeFormat(lang==='el'?'el-GR':'en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(value+'T12:00:00Z')):'—';
  const month=value=>new Intl.DateTimeFormat(lang==='el'?'el-GR':'en-GB',{month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(value+'-01T12:00:00Z'));
  const regionName=r=>({national:L('Πανελλαδικά','Nationwide'),south:L('Αττική & Νότια Ελλάδα','Attica & South Greece'),north:L('Βόρεια Ελλάδα','North Greece'),multi:L('Πολλαπλές περιφερειακές πηγές','Multiple regional sources')}[r]||'');
  const typeName=t=>t==='BET'?L('Βετεράνοι','Veterans'):t==='ANE'?L('Ανεξάρτητοι','Independent'):t==='WOMEN'?L('Γυναίκες','Women'):L('Γενικός πίνακας','Overall ranking');
  const listName=s=>/^BET |^ANE /.test(s)?typeName(s.split(' ')[0])+' · '+s.slice(4):s==='ΓΥΝΑΙΚΩΝ'?L('Γυναίκες · όλες οι ηλικίες','Women · all ages'):s==='ΓΕΝΙΚΟΣ'?L('Γενικός πίνακας','Overall ranking'):s;
  const navItems=[['home','Αρχική','Overview'],['matches','Αγώνες','Matches'],['players','Αθλητές','Players'],['rankings','Κατατάξεις','Rankings'],['teams','Ομάδες','Teams'],['events','Διοργανώσεις','Events'],['h2h','Σύγκριση','Head to head']];
  function route(){const [path,query='']=(location.hash.slice(1)||'home').split('?');const [name,rawId]=path.split('/');const params=new URLSearchParams(query),redirect=id=>db.player_redirects?.[id]||id;const id=name==='player'?redirect(rawId):rawId;for(const k of ['p1','p2'])if(params.has(k))params.set(k,redirect(params.get(k)));return {name,id,params};}
  let current=route();
  const param=(name,fallback='')=>current.params.get(name)||fallback;
  const href=(path,params={})=>'#'+path+(Object.keys(params).length?'?'+new URLSearchParams(params):'');
  const link=(path,text,params={})=>`<a href="${E(href(path,params))}">${E(text)}</a>`;
  const pLink=id=>link('player/'+id,players.get(id)?.name||id);
  const cLink=id=>clubs.has(id)?link('team/'+id,clubs.get(id).name):'—';
  function external(url,text,cls='source-link'){return /^https?:\/\//.test(url||'')?`<a class="${cls}" href="${E(url)}" target="_blank" rel="noopener noreferrer">${E(text)}</a>`:'—';}
  const sourceLink=(id,row)=>external(sources.get(id)?.url,L('Πηγή','Source')+(row?' · '+row:''));
  const empty=text=>`<div class="empty">${E(text||L('Δεν βρέθηκαν εγγραφές για αυτά τα φίλτρα.','No records match these filters.'))}</div>`;
  const table=(heads,body)=>`<div class="table-wrap"><table><thead><tr>${heads.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${body}</tbody></table></div>`;
  const field=(name,label,value,placeholder='')=>`<div class="field grow"><label for="filter-${name}">${E(label)}</label><input id="filter-${name}" data-filter="${name}" type="search" value="${E(value)}" placeholder="${E(placeholder)}" autocomplete="off"></div>`;
  function select(name,label,options,value){return `<div class="field"><label for="filter-${name}">${E(label)}</label><select id="filter-${name}" data-filter="${name}">${options.map(([v,t])=>`<option value="${E(v)}" ${v===value?'selected':''}>${E(t)}</option>`).join('')}</select></div>`;}
  const all=L('Όλα','All');
  function pageHead(title,description='',actions=''){return `<div class="page-head"><div><div class="eyebrow">POFEPA STATS</div><h1>${E(title)}</h1>${description?`<p>${E(description)}</p>`:''}</div>${actions}</div>`;}
  function breadcrumb(label,path){return `<div class="breadcrumb">${link(path,label)} / ${L('Στοιχεία','Details')}</div>`;}
  function paged(rows,render,pageKey="page",pageSize=40){const page=Math.min(Math.max(0,Number(param(pageKey))||0),Math.max(0,Math.ceil(rows.length/pageSize)-1));const start=page*pageSize;
    return `<div class="count" role="status">${num(rows.length)} ${L('εγγραφές','records')}</div><div class="panel">${rows.length?render(rows.slice(start,start+pageSize)):empty()}${rows.length>pageSize?`<div class="pager"><span>${num(start+1)}–${num(Math.min(start+pageSize,rows.length))} / ${num(rows.length)}</span><div><button data-page="${page-1}" data-page-key="${pageKey}" ${page===0?'disabled':''}>${L('Προηγούμενα','Previous')}</button><button data-page="${page+1}" data-page-key="${pageKey}" ${start+pageSize>=rows.length?'disabled':''}>${L('Επόμενα','Next')}</button></div></div>`:''}</div>`;}
  function scopeNote(){return `<div class="notice">${L('Τα στατιστικά αφορούν μόνο τους εισαγμένους αγώνες.','Statistics cover imported matches only.')} ${link('about',L('Δείτε την κάλυψη και τις πηγές.','See coverage and sources.'))}</div>`;}
  function metric(value,label,cls=''){return `<div class="metric ${cls}"><strong>${value}</strong><span>${E(label)}</span></div>`;}
  function statCards(s){return `<div class="metric-grid">${metric(num(s.played),L('Αγώνες','Matches'))}${metric(num(s.wins),L('Νίκες','Wins'),'win')}${metric(num(s.losses),L('Ήττες','Losses'),'loss')}${metric(percent(s.winRate),L('Ποσοστό νικών','Win rate'))}</div>`;}
  function matchTable(rows,player=''){return '<div class="match-table">'+table([L('Ημερομηνία','Date'),L('Αθλητές','Players'),L('Σετ','Games'),L('Διοργάνωση','Competition'),L('Τεκμηρίωση','Evidence')],rows.map(m=>{
    const ids=player&&m.p2===player?[m.p2,m.p1]:[m.p1,m.p2];const scores=ids[0]===m.p1?m.score:[...m.score].reverse();
    const event=events.get(m.event);return `<tr><td>${datefmt(m.date)}<span class="meta">${E((m.regions||[m.region]).map(regionName).join(" · "))}</span></td><td class="match-players">${ids.map((id,i)=>`<a class="${scores[i]>scores[1-i]?'winner':''}" href="#player/${E(id)}"><span>${E(players.get(id)?.name||id)}</span><span class="mobile-result">${scores[i]}</span></a>`).join('')}</td><td class="match-scores">${scores.map((s,i)=>`<span class="${s>scores[1-i]?'winner':''}">${s}</span>`).join('')}</td><td>${link('event/'+m.event,event.name)}<span class="meta">${event.season}</span></td><td>${[...(m.evidence||[{source:m.source,row:m.row}]),...(m.document_evidence||[])].map(e=>sourceLink(e.source,e.row)).join("<br>")}${Evidence.render(m,{lang,escape:E,playerName:id=>players.get(id)?.name||id,sourceLink,datefmt})}</td></tr>`;}).join(''))+'</div>';}
  function fixtureTable(rows){return table([L('Αγωνιστική','Round'),L('Γηπεδούχος','Home team'),L('Σκορ','Score'),L('Φιλοξενούμενος','Away team'),L('Ημερομηνία / ορισμός','Date / deadline'),L('Πηγή','Source')],rows.map(f=>`<tr><td>${E(f.round)}</td><td class="player-cell">${cLink(f.clubs[0])}</td><td class="score">${f.score?f.score.join(' – '):'—'}</td><td class="player-cell">${cLink(f.clubs[1])}</td><td>${f.date?datefmt(f.date):E(f.deadline)||'—'}<span class="meta">${E(f.schedule_note)}</span></td><td>${f.sheet_url?external(f.sheet_url,L('Φύλλο αγώνα','Match sheet')):sourceLink(f.source)}${f.page?'<span class="meta">'+(/\.pdf$/i.test(sources.get(f.source)?.url)?'PDF · '+f.page:L('Εικόνα','Image'))+'</span>':''}${f.rubbers?rubberDetails(f.rubbers):''}</td></tr>`).join(''));}
  function rubberDetails(rows){return `<details><summary>${L('Επιμέρους αγώνες','Individual results')} (${rows.length})</summary>${rows.map(r=>`<p>${r.status==='walkover'?E(r.names.join(' / '))+' ('+L('άνευ αγώνα','walkover')+')':r.kind==='singles'?r.players.map(pLink).join(' / '):E((r.home||r.names||[]).join(' / '))+' — '+E((r.away||[]).join(' / '))+' ('+L('διπλό','doubles')+')'} <b>${r.score.join('–')}</b></p>`).join('')}</details>`;}
  function matchSheetCoverage(){
    const c=db.coverage.match_sheets;if(!c)return '';
    const rows=[...c.reviews].sort((a,b)=>b.date.localeCompare(a.date));
    return `<section class="panel panel-pad"><h2>${L('Φύλλα αγώνων · πρόοδος εισαγωγής','Match sheets · import progress')}</h2>
      <p>${num(c.reviewed)} / ${num(c.linked)} ${L('συνδεδεμένα φύλλα ελέγχθηκαν, με προτεραιότητα στα νεότερα.','linked sheets reviewed, prioritising the newest.')}</p>
      <p>${num(c.imported_sheets??c.reviews.length)} ${L('φύλλα εισήχθησαν','sheets imported')} · ${num(c.held||0)} ${L('χρειάζονται διευκρίνιση','need clarification')} · ${num(c.pending)} ${L('δεν έχουν ακόμη ελεγχθεί','not yet reviewed')}</p>
      <p>${num(c.imported)} ${L('νέοι ατομικοί αγώνες','new singles matches')} · ${num(c.corroborated)} ${L('επιβεβαιωμένοι υπάρχοντες','existing results confirmed')} · ${num(c.excluded_walkovers)} ${L('άνευ αγώνα εξαιρέθηκαν','walkovers excluded')}</p>
      ${c.unavailable?`<p>${num(c.unavailable)} ${L('φύλλα δεν είναι διαθέσιμα στον διακομιστή της πηγής','sheets are unavailable on the source server')}</p>`:''}
      ${Object.entries(c.seasons||{}).slice(0,2).map(([season,s])=>`<p><strong>${E(season)}</strong>: ${num(s.reviewed)} / ${num(s.linked)} ${L('ελεγμένα','reviewed')} · ${num(s.accepted)} ${L('εισήχθησαν','imported')} · ${num(s.held)} ${L('χρειάζονται διευκρίνιση','need clarification')} · ${num(s.pending)} ${L('σε αναμονή ελέγχου','awaiting review')}${s.unavailable?` · ${num(s.unavailable)} ${L('μη διαθέσιμα','unavailable')}`:''}</p>`).join('')}
      ${c.excluded_team_walkovers?`<p>${num(c.excluded_team_walkovers)} ${L('ομαδικοί αγώνες δεν διεξήχθησαν · χωρίς προσθήκη ατομικών αποτελεσμάτων','team fixtures were not played · no individual results added')}</p>`:''}
      <p>${L('Οι χειρόγραφες ταυτότητες ελέγχονται με τον ΔΑΙ, το όνομα, την ομάδα και τις προηγούμενες πηγές. Οι κατατάξεις παραμένουν όπως δημοσιεύονται στους επίσημους πίνακες.','Handwritten identities are checked against registration numbers, names, teams and previous sources. Rankings remain as published in the official lists.')}</p>
      ${c.issues?.length?`<details><summary>${L('Φύλλα που χρειάζονται διευκρίνιση','Sheets needing clarification')} (${c.issues.length})</summary>${table([L('Φύλλο αγώνα','Match sheet'),L('Εκκρεμότητα','Outstanding issue')],c.issues.map(r=>`<tr><td>${external(r.url,decodeURIComponent(r.url.split('/').at(-1)))}</td><td>${E(L(r.details_el||r.details,r.details))}</td></tr>`).join(''))}</details>`:''}
      ${table([L('Ημερομηνία','Date'),L('Φύλλο αγώνα','Match sheet'),L('Νέοι αγώνες','New matches'),L('Ήδη στο αρχείο','Already archived')],rows.map(r=>`<tr><td>${datefmt(r.date)}</td><td>${external(r.url,decodeURIComponent(r.url.split('/').at(-1)))}</td><td>${r.imported||0}</td><td>${r.corroborated||0}</td></tr>`).join(''))}</section>`;
  }
  function documentReviews(){const rows=db.coverage.document_reviews||[];const labels={results_imported:L('Εισήχθησαν αποτελέσματα','Results imported'),standings_only:L('Μόνο βαθμολογίες ομάδων','Team standings only'),no_reported_results:L('Δεν δημοσιεύονται σκορ','No reported scores'),source_conflict:L('Αντιφατικές ονομασίες στην πηγή','Conflicting team labels in source')};return `<section class="panel panel-pad"><h2>${L('Έλεγχος PDF και εικόνων','PDF and image review')}</h2><p>${num(rows.length)} ${L('αρχεία ελέγχθηκαν. Τα ομαδικά σκορ δεν προσμετρώνται ως ατομικοί αγώνες. Οι εικόνες βαθμολογίας δεν δίνουν αποτελέσματα συγκεκριμένων συναντήσεων.','documents reviewed. Team scores do not count as singles matches. Standings images do not provide individual fixture results.')}</p>${table([L('Πηγή','Source'),L('Περίοδος','Season'),L('Αποτελέσματα','Results'),L('Έλεγχος','Review')],rows.map(r=>`<tr><td>${external(r.url,decodeURIComponent(r.url.split('/').at(-1)))}</td><td>${E(r.season)}</td><td>${num(r.fixtures||0)}</td><td>${E(labels[r.review_status]||r.review_status)}${r.review_issues?.length?'<span class="meta">'+r.review_issues.length+' '+L('σκορ εξαιρέθηκαν','scores omitted')+'</span>':''}</td></tr>`).join(''))}</section>`;}
  function rankingTable(rows,snapshot){return table(['#',L('Αθλητής','Player'),L('Ομάδα στην πηγή','Team in source'),L('Βαθμοί','Points'),L('Κατηγορία','Category')],rows.map(r=>`<tr><td class="rank-num ${r[1]!==null&&r[1]<=3?'rank-top':''}">${r[1]??'—'}</td><td class="player-cell">${pLink(r[0])}<span class="meta">${players.get(r[0]).registration?L('ΔΑΙ','ID')+' '+E(players.get(r[0]).registration):L('Χωρίς ΔΑΙ στην πηγή','No source registration')}</span></td><td>${cLink(r[3])}</td><td class="number"><b>${num(r[2],3)}</b></td><td><span class="badge neutral">${E(r[4])}</span></td></tr>`).join(''));}
  function home(){const bracket=db.snapshots.find(s=>s.region==='national'&&s.period===latestPeriod&&s.list==='BET 40-49');
    const latestEvents=db.events.filter(e=>e.kind==='singles'&&e.region==='national').slice(0,4);
    return `<section class="hero"><div class="wrap"><div class="hero-grid"><div><div class="eyebrow">${L('ΤΟ ΑΡΧΕΙΟ ΤΟΥ ΠΟΦΕΠΑ','THE POFΕPA ARCHIVE')}</div><h1>${L('Κάθε αγώνας.<br><span>Η δική σου διαδρομή.</span>','Every match.<br><span>Your table tennis story.</span>')}</h1><p>${L('Αγώνες, αθλητές και κατατάξεις ανά ηλικία και περιοχή. Εξερεύνησε τα αποτελέσματα πίσω από τους αριθμούς.','Matches, players and rankings by age and region. Explore the results behind the numbers.')}</p><form id="home-search" class="hero-search"><input name="q" aria-label="${L('Αναζήτηση αθλητή','Search players')}" placeholder="${L('Όνομα αθλητή ή αριθμός ΔΑΙ…','Player name or registration number…')}" required><button class="primary">${L('Αναζήτηση','Search')}</button></form></div><aside class="hero-aside"><small>${L('ΤΕΛΕΥΤΑΙΑ ΠΑΝΕΛΛΑΔΙΚΗ ΚΑΤΑΤΑΞΗ','LATEST NATIONAL RANKING')}</small><div class="big-date">${month(latestPeriod)}</div><p>${L('Βετεράνοι & ανεξάρτητοι, ανά ηλικιακή κατηγορία. Ιστορικοί πίνακες Βόρειας και Νότιας Ελλάδας.','Veterans & independent players, by age bracket. Historical North and South Greece rankings.')}</p>${link('rankings',L('Εξερεύνηση κατατάξεων','Explore rankings'))}</aside></div><div class="stats-band">${[[db.coverage.matches,L('Εισαγμένοι ατομικοί αγώνες','Imported singles matches')],[db.coverage.ranked_players,L('Προφίλ σε κατατάξεις','Ranked profiles')],[db.coverage.reported_fixtures,L('Ομαδικά αποτελέσματα','Reported team results')],[db.coverage.ranking_periods.length,L('Μήνες κατάταξης','Ranking months')]].map(([n,t])=>`<div class="stat"><strong>${num(n)}</strong><span>${t}</span></div>`).join('')}</div></div></section><main id="main" class="wrap main">${scopeNote()}<div class="grid-two"><section><div class="section-title"><h2>${L('Κατάταξη ηλικιακής κατηγορίας','Age-bracket ranking')}</h2>${link('rankings',L('Όλοι οι πίνακες','All rankings'))}</div><p class="muted">${L('Πανελλαδικά · Βετεράνοι 40–49','Nationwide · Veterans 40–49')} · ${month(latestPeriod)}</p><div class="panel">${rankingTable(bracket.rows.slice(0,6),bracket)}</div></section><section><div class="section-title"><h2>${L('Διοργανώσεις','Competitions')}</h2>${link('events',L('Όλες','View all'))}</div><p class="muted">${L('Αγωνιστική περίοδος 2026–2027','2026–2027 season')}</p><div class="panel">${latestEvents.map(e=>`<article class="event-row"><span class="badge">${regionName(e.region)}</span><h3>${link('event/'+e.id,e.name)}</h3><small>${num(e.match_count??db.matches.filter(m=>m.event===e.id).length)} ${L('αγώνες στο αρχείο','archived matches')}</small></article>`).join('')}</div></section></div><div class="section-title"><h2>${L('Πρόσφατα αποτελέσματα στο αρχείο','Latest archived results')}</h2>${link('matches',L('Όλοι οι αγώνες','All matches'))}</div><div class="panel">${matchTable(db.matches.slice(0,6))}</div><p class="chart-note">${L('Έλεγχος πηγών','Sources checked')}: ${datefmt(db.coverage.as_of)} · ${L('Ατομικά αποτελέσματα έως','Singles results through')}: ${datefmt(db.coverage.match_date_max)}</p></main>`;
  }
  function rankings(){
    const region=param('region','national');const periods=[...new Set(db.snapshots.filter(s=>s.region===region).map(s=>s.period))].sort().reverse();
    const period=periods.includes(param('period'))?param('period'):periods[0];
    const kind=param('class','BET');const relevant=db.snapshots.filter(s=>s.region===region&&s.period===period);
    const ages=relevant.filter(s=>s.list.startsWith(kind+' ')).map(s=>s.list.slice(4));
    const age=ages.includes(param('age'))?param('age'):ages.includes('40-49')?'40-49':ages[0];
    const list=kind==='WOMEN'?'ΓΥΝΑΙΚΩΝ':kind==='GENERAL'?'ΓΕΝΙΚΟΣ':kind+' '+age;
    const snap=relevant.find(s=>s.list===list);
    const rows=(snap?.rows||[]).filter(r=>search(players.get(r[0]).name+' '+players.get(r[0]).registration+' '+(clubs.get(r[3])?.name||''),param('q'))).sort((a,b)=>(a[1]??Infinity)-(b[1]??Infinity));
    return pageHead(L('Κατατάξεις ανά ηλικία & περιοχή','Rankings by age & region'),L('Οι θέσεις διατηρούν τη σειρά της επίσημης λίστας για τη συγκεκριμένη περιοχή και ηλικιακή κατηγορία.','Positions retain the official order within the selected region and age bracket.'))+
      `<div class="toolbar">${select('region',L('Περιοχή','Region'),['national','south','north'].map(r=>[r,regionName(r)]),region)}${select('class',L('Αγωνιστική κατηγορία','Player division'),['BET','ANE','WOMEN','GENERAL'].map(t=>[t,typeName(t)]),kind)}${ages.length?select('age',L('Ηλικιακή κατηγορία','Age bracket'),ages.map(a=>[a,a]),age):''}${select('period',L('Μήνας πηγής','Source month'),periods.map(p=>[p,month(p)]),period)}${field('q',L('Αναζήτηση','Search'),param('q'),L('Όνομα, ΔΑΙ ή ομάδα','Name, ID or team'))}</div>`+
      `<div class="notice">${L('Από τον Σεπτέμβριο 2026 οι πίνακες Βόρειας και Νότιας Ελλάδας ενοποιήθηκαν. Οι ξεχωριστοί περιφερειακοί πίνακες εδώ φτάνουν έως τον Ιούνιο 2026.','North and South rankings were unified from September 2026. Separate regional lists here run through June 2026.')} ${kind==='WOMEN'?L('Η πηγή δημοσιεύει ενιαίο πίνακα γυναικών, χωρίς ξεχωριστές ηλικιακές λίστες.','The source publishes one women’s table, without separate age-bracket lists.'):''}</div>`+
      (snap?`<div class="section-title"><h2>${E(listName(snap.list))}</h2>${sourceLink(snap.source)}</div><p class="chart-note">${E(regionName(region))} · ${month(period)} · ${L('Θέση εντός του επιλεγμένου πίνακα. Δεν υπολογίζεται ξανά μετά την αναζήτηση.','Rank within this list. Search does not renumber positions.')}</p>`+paged(rows,r=>rankingTable(r,snap)):empty());
  }
  function playerList(){const q=param('q'),category=param('category'),sort=param('sort','points');
    let rows=db.players.filter(p=>search([p.name,p.aliases.join(' '),p.registration,clubs.get(p.club)?.name].join(' '),q)&&(!category||p.category===category));
    rows.sort((a,b)=>sort==='name'?a.name.localeCompare(b.name,'el'):sort==='wins'?(statsByPlayer.get(b.id).wins-statsByPlayer.get(a.id).wins):sort==='played'?(statsByPlayer.get(b.id).played-statsByPlayer.get(a.id).played):(latestRows.get(b.id)?.[2]??-Infinity)-(latestRows.get(a.id)?.[2]??-Infinity));
    return pageHead(L('Αθλητές','Players'),L('Αναζήτησε όνομα, αριθμό ΔΑΙ ή ομάδα και άνοιξε το προφίλ ενός αθλητή.','Search by name, registration number or team, then open a player profile.'))+
      `<div class="toolbar">${field('q',L('Αναζήτηση αθλητή','Search players'),q,L('Όνομα, ΔΑΙ ή ομάδα','Name, ID or team'))}${select('category',L('Κατηγορία','Category'),[['',L('Όλες οι κατηγορίες','All categories')],...[...new Set(db.players.map(p=>p.category).filter(Boolean))].sort().map(c=>[c,c])],category)}${select('sort',L('Ταξινόμηση','Sort by'),[['points',L('Βαθμοί τελευταίας κατάταξης','Latest ranking points')],['wins',L('Νίκες στο αρχείο','Archived wins')],['played',L('Αγώνες στο αρχείο','Archived matches')],['name',L('Όνομα','Name')]],sort)}</div>`+
      paged(rows,rs=>table([L('Αθλητής','Player'),L('Ομάδα · τελευταία καταγραφή','Team · latest observation'),L('Κατηγορία','Category'),L('Βαθμοί','Points'),L('Αγώνες','Played'),L('Ν–Η','W–L'),L('Νίκες %','Win %')],rs.map(p=>{const s=statsByPlayer.get(p.id);return `<tr><td class="player-cell">${pLink(p.id)}<span class="meta">${p.provisional?L('Μη συνδεδεμένη ταυτότητα','Unresolved identity'):p.registration?L('ΔΑΙ','ID')+' '+p.registration:L('Χωρίς ΔΑΙ στην πηγή','No source registration')}</span></td><td>${cLink(p.club)}<span class="meta">${month(p.period)}</span></td><td>${E(p.category)||'—'}</td><td class="number">${num(latestRows.get(p.id)?.[2],3)}</td><td class="number">${num(s.played)}</td><td class="number">${s.wins}–${s.losses}</td><td class="number">${percent(s.winRate)}</td></tr>`;}).join('')));
  }
  function historyChart(history){history=history.filter(h=>h.row[2]!==null);if(!history.length)return empty(L('Δεν υπάρχει κατάταξη για αυτή την επιλογή.','No ranking history for this selection.'));
    const low=Math.min(...history.map(h=>h.row[2])),high=Math.max(...history.map(h=>h.row[2]));const span=Math.max(high-low,10);
    const points=history.map((h,i)=>[52+i*500/Math.max(history.length-1,1),145-(h.row[2]-low)*100/span]);
    return `<svg class="chart" viewBox="0 0 600 200" role="img" aria-label="${L('Ιστορικό βαθμών κατάταξης. Οι τιμές παρατίθενται και στον πίνακα.','Ranking points history. Values are also listed in the table.')}"><path d="M45 35V150H570" fill="none" stroke="#dce5e7"/><polyline points="${points.map(p=>p.join(',')).join(' ')}" fill="none" stroke="#00776e" stroke-width="3"/>${points.map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="4" fill="#00776e"><title>${E(month(history[i].period))}: ${num(history[i].row[2],3)}</title></circle>${i===0||i===points.length-1||i%Math.max(1,Math.ceil(points.length/5))===0?`<text x="${x}" y="${Math.max(20,y-13)}" text-anchor="middle">${num(history[i].row[2],1)}</text><text x="${x}" y="180" text-anchor="middle">${history[i].period.slice(5)}/${history[i].period.slice(2,4)}</text>`:''}`).join('')}</svg>`;
  }
  function playerDetail(id) {
    const p=players.get(id);if(!p)return notFound();
    const rows=matchesByPlayer.get(id)||[];
    const seasons=[...new Set(rows.map(m=>events.get(m.event).season))].sort().reverse();
    const filtered=rows.filter(m=>!param('season')||events.get(m.event).season===param('season'));
    const s=stats(filtered,id);
    const history=playerHistories.get(id)||db.snapshots.flatMap(s=>(s.rows||[]).filter(r=>r[0]===id).map(row=>({...s,row})));
    const sortedHistory=[...history].sort((a,b)=>b.period.localeCompare(a.period)||a.region.localeCompare(b.region)||a.list.localeCompare(b.list));
    const charts=['north','south','national'].map(region=>({region,rows:history.filter(h=>h.region===region&&h.list==='ΓΕΝΙΚΟΣ').sort((a,b)=>a.period.localeCompare(b.period))})).filter(g=>g.rows.length);
    const rankingRows=rs=>table([L('Μήνας','Month'),L('Περιοχή','Region'),L('Πίνακας / ηλικία','List / age bracket'),'#',L('Βαθμοί','Points'),L('Πηγή','Source')],rs.map(h=>`<tr><td>${month(h.period)}</td><td>${regionName(h.region)}</td><td>${E(listName(h.list))}</td><td>${h.row[1]??'—'}</td><td class="number">${num(h.row[2],3)}</td><td>${sourceLink(h.source,h.row[5])}</td></tr>`).join(''));
    return breadcrumb(L('Αθλητές','Players'),'players')+
      `<div class="profile-head"><div class="profile-identity"><div class="avatar" aria-hidden="true">${E(p.name.split(' ').slice(0,2).map(n=>n[0]).join(''))}</div><div><div class="eyebrow">${p.registration?'ΔΑΙ '+p.registration:L('Προσωρινή ταυτότητα','Provisional identity')}</div><h1>${E(p.name)}</h1><p>${cLink(p.club)} · ${E(p.category)} · ${L('Καταγραφή','Observed')} ${month(p.period)}</p></div></div><a class="button secondary" href="${E(href('h2h',{p1:id}))}">${L('Σύγκριση αθλητή','Compare player')}</a></div>`+
      `<nav class="profile-jumps" aria-label="${L('Ενότητες αθλητή','Athlete sections')}"><button type="button" data-jump="athlete-matches">${L('Αγώνες','Matches')}</button><button type="button" data-jump="athlete-rankings">${L('Κατατάξεις','Rankings')}</button><button type="button" data-jump="athlete-analysis">${L('Ανάλυση','Breakdown')}</button></nav>`+
      (p.provisional?`<div class="notice">${L('Αυτή η εγγραφή δεν συνδέθηκε με βεβαιότητα με αριθμό ΔΑΙ. Οι αγώνες της παραμένουν χωριστά από ομώνυμους αθλητές.','This source identity could not be resolved to a registration number. Its matches remain separate from players with the same name.')}</div>`:'')+
      (p.identity_conflict?`<div class="notice">${L('Ο ίδιος ΔΑΙ εμφανίζεται με διαφορετικά ονόματα στις πηγές. Οι διαφορετικές εγγραφές διατηρούνται χωριστές μέχρι να ελεγχθούν.','This registration number appears under different names in the sources. Those identities remain separate pending review.')}</div>`:'')+
      `<div class="toolbar athlete-season">${select('season',L('Περίοδος αγώνων','Match season'),[['',L('Όλες οι περίοδοι','All seasons')],...seasons.map(v=>[v,v])],param('season'))}<p class="chart-note">${L('Η περίοδος αλλάζει τους αγώνες και τα στατιστικά. Οι κατατάξεις παραμένουν πλήρεις.','Season filters matches and statistics. Ranking history always includes every recorded list.')}</p></div>`+
      statCards(s)+scopeNote()+
      `<section aria-labelledby="athlete-matches"><div class="section-title"><h2 id="athlete-matches" tabindex="-1">${L('Ιστορικό αγώνων','Match history')}</h2><button class="button secondary" data-export="player" data-id="${E(id)}">CSV</button></div><p class="chart-note">${L('Οι πιο πρόσφατοι αγώνες πρώτα. Όλο το ιστορικό είναι διαθέσιμο στις επόμενες σελίδες.','Latest matches first. Continue through the pages to explore the full history.')}</p>${paged(filtered,r=>matchTable(r,id),'page',10)}</section>`+
      `<div class="grid-two"><section class="panel panel-pad"><h2>${L('Εξέλιξη βαθμών κατάταξης','Ranking points history')}</h2><p class="chart-note">${L('Βαθμοί γενικής κατάταξης ανά περιοχή. Όλες οι καταγεγραμμένες κατηγορίες εμφανίζονται στον πίνακα παρακάτω.','Overall ranking points by region. Every recorded category is included in the table below.')}</p>${charts.map(g=>`<h3>${regionName(g.region)}</h3>${historyChart(g.rows)}`).join('')||empty()}</section><section class="panel panel-pad" aria-labelledby="athlete-analysis"><h2 id="athlete-analysis" tabindex="-1">${L('Ανάλυση αγώνων','Match breakdown')}</h2><dl class="details-list"><dt>${L('Σετ υπέρ / κατά','Games won / lost')}</dt><dd>${s.gamesWon} / ${s.gamesLost}</dd><dt>${L('Αγώνες πέντε σετ','Five-game matches')}</dt><dd>${s.deciding}</dd><dt>${L('Νίκες στο πέμπτο σετ','Deciding-game wins')}</dt><dd>${s.decidingWins}</dd><dt>${L('Διαφορετικοί αντίπαλοι','Distinct opponents')}</dt><dd>${new Set(filtered.map(m=>m.p1===id?m.p2:m.p1)).size}</dd></dl><p class="chart-note" style="margin-top:22px">${L('Τα αποτελέσματα δίνουν τελικό σκορ σετ, όχι πόντους ανά σετ. Δεν υπολογίζονται στατιστικά πόντων.','Results give final game scores, not individual points. Point-level statistics are unavailable.')}</p><details><summary>${L('Πώς συνδέονται οι αγώνες','How matches are linked')}</summary><p class="chart-note">${L('Οι αγώνες συνδέονται με ακριβές όνομα και ομάδα ή μοναδικό ακριβές όνομα στον ίδιο μήνα. Σύνδεση μόνο με όνομα ή με διαφορετική ομάδα είναι προσωρινή.','Matches link by exact name and team, or by a unique exact name in the same month’s lists. Name-only links and links with a different recorded team are provisional.')}</p></details></section></div>`+
      `<section aria-labelledby="athlete-rankings"><div class="section-title"><h2 id="athlete-rankings" tabindex="-1">${L('Όλες οι κατατάξεις','All rankings')}</h2></div><p class="chart-note">${L('Όλες οι περιοχές και ηλικιακές κατηγορίες, με τις νεότερες εγγραφές πρώτα.','Every region and age category, with the latest records first.')}</p>${paged(sortedHistory,rankingRows,'rpage',10)}</section>`;
  }
  function matchList(){const view=param('view','singles');const relevantEvents=db.events.filter(e=>e.kind===(view==='singles'?'singles':'fixtures'));
    let rows=(view==='singles'?db.matches:db.fixtures).filter(m=>(!param('event')||m.event===param('event'))&&(!param('region')||(m.regions||[m.region]).includes(param('region')))&&search(view==='singles'?m.names.join(' '):m.home+' '+m.away,param('q'))&&(!param('season')||events.get(m.event).season===param('season'))&&(!param('status')||m.status===param('status')));
    return pageHead(L('Αγώνες & αποτελέσματα','Matches & results'),view==='singles'?L('Μόνο ολοκληρωμένα σκορ 3–0, 3–1 και 3–2.','Completed 3–0, 3–1 and 3–2 scores only.'):L('Οι ημερομηνίες ορισμού είναι προθεσμίες της πηγής, όχι επιβεβαιωμένες ημερομηνίες διεξαγωγής.','Source deadlines are not confirmed dates of play.'),view==='singles'?`<button class="button secondary" data-export="matches">${L('Εξαγωγή CSV','Export CSV')}</button>`:'')+
      `<div class="chips"><a class="${view==='singles'?'active':''}" href="#matches">${L('Ατομικοί αγώνες','Singles')}</a><a class="${view==='teams'?'active':''}" href="#matches?view=teams">${L('Ομαδικές συναντήσεις','Team fixtures')}</a></div><div class="toolbar">${field('q',L('Αναζήτηση','Search'),param('q'),view==='singles'?L('Όνομα αθλητή','Player name'):L('Όνομα ομάδας','Team name'))}${select('event',L('Διοργάνωση','Competition'),[['',L('Όλες οι διοργανώσεις','All competitions')],...relevantEvents.map(e=>[e.id,e.name+(e.region?' · '+regionName(e.region):'')])],param('event'))}${view==='singles'?select('region',L('Περιοχή πηγής','Source region'),[['',L('Όλες οι περιοχές','All regions')],...['national','south','north'].map(r=>[r,regionName(r)])],param('region')):select('status',L('Κατάσταση','Status'),[['',L('Όλες','All')],['reported',L('Με αποτέλεσμα','Reported results')],['scheduled',L('Χωρίς αποτέλεσμα','No result yet')]],param('status'))}</div>`+paged(rows,r=>view==='singles'?matchTable(r):fixtureTable(r));
  }
  function eventList(){const rows=db.events.filter(e=>search(e.name+' '+regionName(e.region),param('q'))&&(!param('kind')||e.kind===param('kind'))&&(!param('season')||e.season===param('season')));
    return pageHead(L('Διοργανώσεις','Competitions'),L('Τα ατομικά αποτελέσματα των workbooks και τα προγράμματα των ομαδικών συναντήσεων έχουν ξεχωριστή κάλυψη.','Workbook singles results and published team schedules have separate coverage.'))+`<div class="toolbar">${field('q',L('Αναζήτηση','Search'),param('q'))}${select('kind',L('Δεδομένα','Records'),[['',L('Όλα','All')],['singles',L('Ατομικά αποτελέσματα','Singles results')],['fixtures',L('Ομαδικές συναντήσεις','Team fixtures')]],param('kind'))}${select('season',L('Περίοδος','Season'),[['',L('Όλες','All')],...[...new Set(db.events.map(e=>e.season))].sort().reverse().map(s=>[s,s])],param('season'))}</div>`+paged(rows,rs=>table([L('Διοργάνωση','Competition'),L('Περίοδος','Season'),L('Κάλυψη','Coverage'),L('Εγγραφές','Records')],rs.map(e=>`<tr><td class="player-cell">${link('event/'+e.id,e.name)}<span class="meta">${E(regionName(e.region))}</span></td><td>${e.season}</td><td>${e.kind==='singles'?L('Ατομικοί αγώνες','Singles'):L('Ομαδικές συναντήσεις','Fixtures')}</td><td class="number">${num(e.match_count??(e.kind==='singles'?db.matches:db.fixtures).filter(m=>m.event===e.id).length)}</td></tr>`).join('')));
  }
  function eventDetail(id){const e=events.get(id);if(!e)return notFound();const rows=(e.kind==='singles'?db.matches:db.fixtures).filter(m=>m.event===id);
    return breadcrumb(L('Διοργανώσεις','Competitions'),'events')+pageHead(e.name,e.season+(e.region?' · '+regionName(e.region):''),sourceLink(e.sources[0]))+scopeNote()+(e.kind==='fixtures'?`<div class="notice">${L('Οι ημερομηνίες ορισμού δεν είναι επιβεβαιωμένες ημερομηνίες αγώνα. Δεν συμπεραίνουμε ατομικά αποτελέσματα από το ομαδικό σκορ.','Listed deadlines are not confirmed match dates. Singles results are not inferred from team scores.')}</div>`:'')+paged(rows,r=>e.kind==='singles'?matchTable(r):fixtureTable(r));
  }
  function teamList(){const rows=db.clubs.filter(c=>search(c.name,param('q'))).sort((a,b)=>a.name.localeCompare(b.name,'el'));
    return pageHead(L('Ομάδες','Teams'),L('Ονομασίες όπως καταγράφονται στις πηγές. Παραλλαγές ονομάτων δεν συγχωνεύονται αυτόματα.','Names as recorded by the sources. Spelling variants are not automatically merged.'))+`<div class="toolbar">${field('q',L('Αναζήτηση ομάδας','Search teams'),param('q'))}</div>`+paged(rows,rs=>table([L('Ομάδα','Team'),L('Αθλητές τελευταίου πίνακα','Players in latest ranking'),L('Συναντήσεις στο αρχείο','Archived fixtures')],rs.map(c=>`<tr><td>${cLink(c.id)}</td><td class="number">${num(latestGeneral.rows.filter(r=>r[3]===c.id).length)}</td><td class="number">${num(db.fixtures.filter(f=>f.clubs.includes(c.id)).length)}</td></tr>`).join('')));
  }
  function teamDetail(id){const c=clubs.get(id);if(!c)return notFound();const roster=latestGeneral.rows.filter(r=>r[3]===id),fixtures=db.fixtures.filter(f=>f.clubs.includes(id));
    return breadcrumb(L('Ομάδες','Teams'),'teams')+pageHead(c.name,L('Η σύνθεση βασίζεται στην τελευταία πανελλαδική κατάταξη.','Roster follows the latest national ranking.'))+`<div class="section-title"><h2>${L('Αθλητές','Players')} · ${month(latestPeriod)}</h2></div><div class="panel">${roster.length?rankingTable(roster,latestGeneral):empty()}</div><div class="section-title"><h2>${L('Ομαδικές συναντήσεις','Team fixtures')}</h2></div>`+paged(fixtures,fixtureTable);
  }
  const playerOption=p=>p.name+' · '+(p.registration?'ΔΑΙ '+p.registration:p.id);
  function compare(){const a=players.get(param('p1')),b=players.get(param('p2')),rows=h2h(db.matches,a?.id,b?.id),same=a&&b&&a.id===b.id;
    return pageHead(L('Σύγκριση αθλητών','Head to head'),L('Επίλεξε δύο αθλητές. Η διεύθυνση κρατά τη σύγκριση για να τη μοιραστείς.','Choose two players. The URL preserves your comparison for sharing.'))+`<form id="compare-form" class="panel panel-pad"><div class="compare"><div class="field"><label for="compare-a">${L('Πρώτος αθλητής','First player')}</label><input id="compare-a" name="p1" list="player-options" value="${E(a?playerOption(a):'')}" placeholder="${L('Όνομα ή ΔΑΙ','Name or ID')}" autocomplete="off" required></div><span class="versus">vs</span><div class="field"><label for="compare-b">${L('Δεύτερος αθλητής','Second player')}</label><input id="compare-b" name="p2" list="player-options" value="${E(b?playerOption(b):'')}" placeholder="${L('Όνομα ή ΔΑΙ','Name or ID')}" autocomplete="off" required></div></div><datalist id="player-options">${db.players.map(p=>`<option value="${E(playerOption(p))}"></option>`).join('')}</datalist><button class="primary" style="margin-top:20px">${L('Σύγκριση','Compare')}</button><p id="compare-error" role="alert" style="margin-top:14px"></p></form>`+scopeNote()+
      (same?empty(L('Επίλεξε δύο διαφορετικούς αθλητές.','Choose two different players.')):a&&b?`<div class="panel compare-score"><div><h2>${pLink(a.id)}</h2><small>${E(a.category)}</small></div><strong>${stats(rows,a.id).wins} : ${stats(rows,b.id).wins}</strong><div><h2>${pLink(b.id)}</h2><small>${E(b.category)}</small></div></div>${rows.length?paged(rows,matchTable):empty(L('Δεν υπάρχουν μεταξύ τους αγώνες στο εισαγμένο αρχείο. Αυτό δεν σημαίνει ότι δεν έχουν αγωνιστεί ποτέ.','No meetings in the imported archive. This does not mean they have never played.'))}`:'');
  }
  function aboutBase(){const c=db.coverage;
    return pageHead(L('Κάλυψη & πηγές','Coverage & sources'),L('Ανεξάρτητο έργο, με την ίδια στατική αρχιτεκτονική του Greek TT Archive. Δεν αποτελεί επίσημη υπηρεσία του ΠΟΦΕΠΑ.','An independent project using the static architecture of Greek TT Archive. Not an official POFΕPA service.'))+
      `<div class="metric-grid">${metric(num(c.matches),L('Ατομικοί αγώνες','Singles matches'))}${metric(num(c.ranking_rows),L('Εγγραφές κατάταξης','Ranking records'))}${metric(num(c.reported_fixtures),L('Ομαδικά αποτελέσματα','Reported fixtures'))}${metric(num(c.provisional_players),L('Μη συνδεδεμένες ταυτότητες','Unresolved identities'))}</div><div class="panel panel-pad prose"><h2>${L('Τι περιλαμβάνει το αρχείο','What the archive includes')}</h2><p>${L('Εισάγονται όλα τα συνδεδεμένα αρχεία Excel του επίσημου αρχείου, από τον Οκτώβριο 2011 έως τον Οκτώβριο 2026. Διατηρούνται οι ξεχωριστοί πίνακες Βόρειας, Νότιας Ελλάδας και οι πανελλαδικοί, ανά ηλικιακή κατηγορία. Από τον Σεπτέμβριο 2026 οι περιφερειακοί πίνακες ενοποιούνται.','Every linked Excel workbook in the official archive is imported, from October 2011 through October 2026. North Greece, Attica & South Greece and national lists retain their separate age-bracket positions. Regional rankings were unified from September 2026.')}</p><p>${L('Ατομικοί αγώνες στις εισαγμένες πηγές','Singles matches in imported sources')}: ${datefmt(c.match_date_min)} – ${datefmt(c.match_date_max)}. ${L('Έλεγχος πηγών','Sources checked')}: ${datefmt(c.as_of)}.</p><h2>${L('Ηλικία και περιοχή','Age and region')}</h2><p>${L('Χρησιμοποιούμε τους επίσημους πίνακες ANE και BET για κάθε ηλικιακό εύρος. Οι κατηγορίες και οι θέσεις λαμβάνονται από το αντίστοιχο φύλλο, δεν υπολογίζονται από έτη γέννησης ή από φιλτραρισμένη γενική κατάταξη. Τα έτη γέννησης δεν περιλαμβάνονται στο αρχείο. Η πηγή δίνει ενιαίο πίνακα γυναικών, όχι χωριστούς ανά ηλικία.','We use the official ANE and BET sheets for each age bracket. Categories and positions come from the relevant sheet, not from birth years or a filtered overall ranking. Birth years are not included. The source supplies one combined women’s list, not separate age lists.')}</p><h2>${L('Τι μετράει ως αγώνας','What counts as a match')}</h2><p>${L('Μετράνε μόνο γραμμές με δύο αθλητές, έγκυρη ημερομηνία και τελικό σκορ 3–0, 3–1 ή 3–2. Bonus, μη τυπικά σκορ (π.χ. 1–0), κενές ή ίδιες ταυτότητες αποκλείονται. Κάθε αποτέλεσμα διατηρεί την πηγή και τη γραμμή του στο αρχείο ή στο φύλλο αγώνα. Δεν εμφανίζονται επιμέρους πόντοι σετ.','Only rows with two players, a valid date and a final 3–0, 3–1 or 3–2 score count. Bonus rows, nonstandard scores (such as 1–0), missing or identical participants are excluded. Each result retains its source and row in the workbook or match sheet. Individual game points are not displayed.')}</p><p>${L('Εξαιρέσεις ανά λόγο','Excluded rows by reason')}: ${Object.entries(c.excluded_rows).map(([k,v])=>E(k)+': '+num(v)).join(' · ')}.</p><h2>${L('Σύνδεση αθλητών','Player identity')}</h2><p>${L('Οι κατατάξεις συνδέονται με τον επίσημο αριθμό ΔΑΙ. Τα μηνιαία φύλλα αποτελεσμάτων Excel δεν έχουν ΔΑΙ: χρησιμοποιούμε ακριβές όνομα και ομάδα στους πίνακες του ίδιου μήνα. Αν η ομάδα είναι κενή, συνδέουμε μόνο μοναδικό όνομα σε αυτούς τους πίνακες και σημειώνουμε την προσωρινή συσχέτιση. Αμφίσημα ονόματα παραμένουν χωριστά. Μοναδικό ακριβές όνομα μπορεί να συνδεθεί προσωρινά όταν διαφέρει η ομάδα. Παλαιότερες λίστες χωρίς ΔΑΙ συνδέονται με ακριβές όνομα και ομάδα ή μοναδικό ακριβές όνομα. Επαναλαμβανόμενα ιστορικά ονόματα παραμένουν χωριστά. Σύνδεση μοναδικού ονόματος με διαφορετική ομάδα σημειώνεται ως προσωρινή.','Rankings link by official DAI registration number where supplied. Monthly Excel results sheets omit DAI: we match exact name and team across the same month’s ranking lists. Unique exact names can be provisionally linked when the team is blank or differs. Ambiguous names remain separate. Before registration numbers appeared, historical rows are linked by an exact name and team, or a unique exact name across registered profiles. Repeated historical names remain separate. Exact-name matches with a different team are marked provisional. No fuzzy name matching is used.')}</p><h2>${L('Περιορισμοί κάλυψης','Coverage limitations')}</h2><p>${L('Τα ατομικά αποτελέσματα περιλαμβάνουν τις μηνιαίες λίστες και τα ελεγμένα φύλλα αγώνων. Τα ομαδικά προγράμματα ενημερώνονται ξεχωριστά και μπορεί να έχουν πιο πρόσφατα σκορ. Οι ημερομηνίες ορισμού δεν θεωρούνται ημερομηνίες διεξαγωγής. Οι αμφίσημες γραμμές, οι μη διαθέσιμες περίοδοι και τα μη αναγνώσιμα τμήματα καταγράφονται αναλυτικά παρακάτω. Δεν συμπληρώνουμε κενά με υποθετικούς αγώνες.','Singles coverage includes imported monthly workbooks and reviewed match sheets. Team schedules are collected separately and may have more recent scores. Scheduled deadlines are not treated as actual play dates. Ambiguous rows, missing periods and unparsed document sections are listed below. Gaps are not filled with inferred results.')}</p><p>${external('https://www.pofepa.gr/',L('Ιστότοπος ΠΟΦΕΠΑ','POFΕPA website'))} · ${external(db.ranking_index,L('Επίσημο αρχείο κατατάξεων','Official ranking archive'))}</p><button class="button secondary" data-export="data">${L('Λήψη δεδομένων JSON','Download dataset JSON')}</button> <button class="button secondary" data-export="matches">${L('Αγώνες CSV','Matches CSV')}</button></div><section class="panel panel-pad"><h2>${L('Εισαγμένες πηγές','Imported sources')}</h2>${table([L('Αρχείο / σελίδα','File / page'),L('Ανάκτηση UTC','Retrieved UTC'),L('SHA-256','SHA-256')],db.sources.map(s=>`<tr><td class="source-cell">${external(s.url,decodeURIComponent(s.url.split('/').at(-1)))}</td><td>${E(s.retrieved_at)}</td><td><details><summary>${s.sha256.slice(0,12)}…</summary><code style="overflow-wrap:anywhere">${s.sha256}</code></details></td></tr>`).join(''))}</section><details class="panel panel-pad"><summary>${L('Σελίδες που χρειάζονται ξεχωριστή εισαγωγή','Pages needing separate ingestion')} (${c.deferred.length})</summary>${table([L('Πηγή','Source'),L('Αιτία','Reason')],c.deferred.map(d=>`<tr><td>${external(d.url,d.label)}</td><td>${E(d.reason)}</td></tr>`).join(''))}</details>`;
  }
  function about(){return matchSheetCoverage()+aboutBase()+documentReviews()+`<section class="panel panel-pad"><h2>${L('ΔΑΙ με διαφορετικά ονόματα','Registration numbers with changed names')}</h2><p>${L('Οι παρακάτω παραλλαγές διατηρούνται σε χωριστά προφίλ μέχρι να ελεγχθούν, ακόμη και όταν φαίνονται σαν απλά ορθογραφικά λάθη.','These variants remain separate profiles pending review, even when they appear to be spelling corrections.')}</p>${table(['ΔΑΙ',L('Ονόματα στις πηγές','Names in source')],db.coverage.identity_conflicts.map(c=>`<tr><td>${E(c.registration)}</td><td>${c.names.map(E).join('<br>')}</td></tr>`).join(''))}</section>`;}
  function notFound(){return pageHead(L('Η σελίδα δεν βρέθηκε','Page not found'))+`<a class="button" href="#home">${L('Επιστροφή στην αρχική','Back to overview')}</a>`;}
  function header(){const active={player:'players',team:'teams',event:'events'}[current.name]||current.name;
    return `<header class="topbar"><div class="wrap top-inner"><a class="brand" href="#home"><span class="brandmark" aria-hidden="true"><svg viewBox="0 0 32 32"><path d="m19 18 8 9" stroke="#f4ab61" stroke-width="5"/><ellipse cx="13" cy="12" rx="10" ry="9" fill="#8adfd2"/><circle cx="27" cy="5" r="3" fill="white"/></svg></span><span><b>POFEPA <span>STATS</span></b><small>${L('ΑΓΩΝΕΣ & ΑΘΛΗΤΕΣ','MATCHES & PLAYERS')}</small></span></a><nav class="nav" aria-label="${L('Κύρια πλοήγηση','Main navigation')}">${navItems.map(([r,el,en])=>`<a href="#${r}" class="${active===r?'active':''}" ${active===r?'aria-current="page"':''}>${L(el,en)}</a>`).join('')}<button class="lang" id="lang" aria-label="${L('Switch to English','Αλλαγή σε Ελληνικά')}">${L('EN','ΕΛ')}</button></nav></div></header>`;
  }
  const snapshotMap=map(db.snapshots);
  async function loadPlayer(id){const p=players.get(id);if(!p||!db.lazy)return;
    const records=await fetchData(p.archive),record=records[id];
    matchesByPlayer.set(id,record.matches);
    playerHistories.set(id,record.history.map(([sid,row])=>({...snapshotMap.get(sid),row})));
  }
  async function prepareView(r){if(!db.lazy)return db.matches;
    if(['teams','team'].includes(r.name)||(r.name==='matches'&&r.params.get('view')==='teams')||(r.name==='event'&&events.get(r.id)?.kind==='fixtures')){
      if(!db.fixtures&&db.archives?.fixtures)db.fixtures=await fetchData(db.archives.fixtures);
    }
    if(r.name==='about'&&db.archives?.about){
      const archive=await fetchData(db.archives.about);
      db.sources=archive.sources;db.coverage=archive.coverage;
      for(const source of db.sources)sources.set(source.id,source);
    }
    if(r.name==='player'){await loadPlayer(r.id);return db.recent_matches;}
    if(r.name==='h2h'){const id=r.params.get('p1');await loadPlayer(id);return matchesByPlayer.get(id)||[];}
    if(r.name==='matches'&&r.params.get('view')!=='teams')return fetchData('data/matches.json.gz');
    if(r.name==='event'&&events.get(r.id)?.kind==='singles')return fetchData(events.get(r.id).archive);
    if(r.name==='rankings'){
      const region=r.params.get('region')||'national',all=db.snapshots.filter(s=>s.region===region);
      const periods=[...new Set(all.map(s=>s.period))].sort().reverse(),period=periods.includes(r.params.get('period'))?r.params.get('period'):periods[0];
      const kind=r.params.get('class')||'BET',relevant=all.filter(s=>s.period===period),ages=relevant.filter(s=>s.list.startsWith(kind+' ')).map(s=>s.list.slice(4));
      const age=ages.includes(r.params.get('age'))?r.params.get('age'):ages.includes('40-49')?'40-49':ages[0];
      const list=kind==='WOMEN'?'ΓΥΝΑΙΚΩΝ':kind==='GENERAL'?'ΓΕΝΙΚΟΣ':kind+' '+age;
      const snap=relevant.find(s=>s.list===list);if(snap&&!snap.rows)snap.rows=await fetchData(snap.archive);
    }
    return db.recent_matches;
  }
  let renderSerial=0;
  function renderError(error,reload=false){
    app.innerHTML=header()+`<main id="main" class="wrap main"><h1>${L('Αδυναμία φόρτωσης','Unable to load data')}</h1><p>${reload?L('Ανανεώστε τη σελίδα για να φορτώσετε ξανά το αρχείο.','Reload the page to load the archive again.'):L('Δοκιμάστε ξανά.','Please retry.')}</p><button id="${reload?'reload':'retry'}">${reload?L('Ανανέωση σελίδας','Reload page'):L('Επανάληψη','Retry')}</button></main>`;
    console.error(error);
  }
  async function render(){const serial=++renderSerial;current=route();document.documentElement.lang=lang;
    const pending=prepareView(current);
    if(db.lazy)app.innerHTML=header()+`<main id="main" class="wrap main"><p role="status">${L('Φόρτωση αρχείου…','Loading archive…')}</p></main>`;
    let loaded;try{loaded=await pending;}catch(error){if(serial===renderSerial)renderError(error);return;}
    if(serial!==renderSerial)return;db.matches=loaded;

    const view={home,rankings,players:playerList,player:()=>playerDetail(current.id),matches:matchList,events:eventList,event:()=>eventDetail(current.id),teams:teamList,team:()=>teamDetail(current.id),h2h:compare,about}[current.name]||notFound;
    let body;try{body=view();}catch(error){renderError(error,true);return;}
    document.title=(players.get(current.id)?.name||events.get(current.id)?.name||clubs.get(current.id)?.name||navItems.find(n=>n[0]===current.name)?.[lang==='el'?1:2]||L('Κάλυψη & πηγές','Coverage & sources'))+' · POFEPA Stats';
    app.innerHTML=header()+(current.name==='home'?body:`<main id="main" class="wrap main">${body}</main>`)+`<footer class="footer"><div class="wrap footer-inner"><div><b>POFEPA STATS</b> · ${db.version==='prototype'?L('Πρωτότυπο','Prototype'):'v'+E(db.version)}<br>${L('Ανεξάρτητο αρχείο · όχι επίσημη υπηρεσία ΠΟΦΕΠΑ.','Independent archive · not an official POFΕPA service.')}</div><div>${link('about',L('Κάλυψη & πηγές','Coverage & sources'))}${external('https://www.pofepa.gr/','pofepa.gr')}${external('https://thanospolimeridis.github.io/greek-tt-stats/','Greek TT Archive')}</div></div></footer>`;
  }
  async function updateFilter(name,value){const focus=document.activeElement?.id;let pos;try{pos=document.activeElement.selectionStart;}catch{}
    const params=new URLSearchParams(current.params);value?params.set(name,value):params.delete(name);if(!['page','rpage'].includes(name)){params.delete('page');params.delete('rpage');}
    if(name==='region'){params.delete('period');params.delete('list');}if(name==='class')params.delete('age');
    history.replaceState(null,'',href(current.name+(current.id?'/'+current.id:''),Object.fromEntries(params)));await render();
    if(focus){const el=document.getElementById(focus);el?.focus();try{el?.setSelectionRange(pos,pos);}catch{}}
  }
  let searchTimer;
  app.addEventListener('input',event=>{if(event.target.matches('input[data-filter]')){clearTimeout(searchTimer);const {filter}=event.target.dataset,value=event.target.value;searchTimer=setTimeout(()=>updateFilter(filter,value),160);}});
  app.addEventListener('change',event=>{if(event.target.matches('select[data-filter]'))updateFilter(event.target.dataset.filter,event.target.value);});
  function jumpToSection(id){const section=document.getElementById(id);if(section){section.focus({preventScroll:true});section.scrollIntoView({block:'start'});}}
  app.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;
    if(button.dataset.jump){jumpToSection(button.dataset.jump);return;}
    if(button.id==='retry')render();
    if(button.id==='reload')location.reload();
    if(button.id==='lang'){lang=lang==='el'?'en':'el';try{localStorage.setItem('pofepa-lang',lang);}catch{}render();}
    if(button.dataset.page!==undefined){const key=button.dataset.pageKey||'page',athlete=current.name==='player';updateFilter(key,button.dataset.page).then(()=>{if(athlete)jumpToSection(key==='rpage'?'athlete-rankings':'athlete-matches');});}
    if(button.dataset.export)exportData(button.dataset.export,button.dataset.id);
  });
  app.addEventListener('submit',event=>{event.preventDefault();const form=event.target;
    if(form.id==='home-search')location.hash=href('players',{q:new FormData(form).get('q')}).slice(1);
    if(form.id==='compare-form'){const values=new FormData(form);const a=db.players.find(p=>playerOption(p)===values.get('p1')),b=db.players.find(p=>playerOption(p)===values.get('p2'));
      if(!a||!b||a.id===b.id){document.getElementById('compare-error').textContent=L('Επίλεξε δύο διαφορετικούς αθλητές από τις προτάσεις.','Select two different players from the suggestions.');return;}
      location.hash=href('h2h',{p1:a.id,p2:b.id}).slice(1);
    }
  });
  async function exportData(kind,id){let content,mime,filename;
    if(kind==='data'){content=JSON.stringify(db.lazy?await fetchData('data/catalog.json.gz'):db);mime='application/json';filename='pofepa-data.json';}
    else{let rows=kind==='player'?(matchesByPlayer.get(id)||[]).filter(m=>!param('season')||events.get(m.event).season===param('season')):db.lazy?await fetchData('data/matches.json.gz'):db.matches;
      if(kind==='matches'&&current.name==='matches')rows=rows.filter(m=>(!param('season')||events.get(m.event).season===param('season'))&&(!param('event')||m.event===param('event'))&&(!param('region')||(m.regions||[m.region]).includes(param('region')))&&search(m.names.join(' '),param('q')));
      const quote=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"';
      const evidenceColumns=['document_sources','correction_flags','correction_original_state','correction_reasons'];
      content='\ufeff'+[['date','player_1','player_2','games_1','games_2','event','region','source','sheet_row','identity_1','identity_2',...evidenceColumns],...rows.map(m=>{const evidence=Evidence.csvFields(m,{sourceUrl:id=>sources.get(id)?.url||''});return [m.date,...m.names,...m.score,events.get(m.event).name,m.region,sources.get(m.source).url,m.row,...m.identity,...evidenceColumns.map(k=>evidence[k])];})].map(r=>r.map(quote).join(',')).join('\r\n');mime='text/csv;charset=utf-8';filename='pofepa-matches.csv';}
    const url=URL.createObjectURL(new Blob([content],{type:mime})),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
  }
  document.querySelector('.skip').addEventListener('click',event=>{event.preventDefault();const main=document.getElementById('main');main.setAttribute('tabindex','-1');main.focus();main.scrollIntoView();});
  window.addEventListener('hashchange',()=>{clearTimeout(searchTimer);render();window.scrollTo(0,0);});
  await render();
})().catch(error=>{document.getElementById('app').innerHTML='<main class="wrap main"><h1>Unable to load archive / Αδυναμία φόρτωσης</h1><p>Please reload the page / Ανανεώστε τη σελίδα.</p></main>';console.error(error);});
